def update_index_for_direction(self, index_direction, index):
        """
        :type index_direction: SliceDirection
        :type index: int
        """
        if index_direction == SliceDirection.FORWARD:
            self._forward_index = index
        elif index_direction == SliceDirection.BACKWARD:
            self._backward_index = index
        else:
            raise ValueError("Invalid index direction")

